def search(lst):
    '''
    You are given a non-empty list of positive integers. Return the greatest integer that is greater than zero, 
    and has a frequency greater than or equal to the value of the integer itself. 
    The frequency of an integer is the number of times it appears in the list.
    If no such a value exist, return -1.
    '''
    # Create a dictionary to store the frequency of each integer in the list
    freq_dict = {}

    # Iterate over the list to count the frequency of each integer
    for num in lst:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1

    # Iterate over the list again to find the greatest integer with a frequency greater than or equal to its value
    for num, freq in freq_dict.items():
        if num > 0 and freq >= num:
            return num

    # If no such integer is found, return -1
    return -1
