def is_multiply_prime(a):
    """
    Checks if a number is the multiplication of 3 prime numbers.

    Args:
        a (int): The number to check.

    Returns:
        bool: True if a is the multiplication of 3 prime numbers, False otherwise.
    """
    def is_prime(n):
        """Checks if a number is prime."""
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Check if a is the product of 3 prime numbers
    for i in range(2, a):
        if a % i == 0 and is_prime(i) and is_prime(a // i):
            return True
    return False
